namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;
    private readonly List<Notification> _notifications =
    [
        new(1, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
        new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)),
        new(3, "New feature available: dark mode.", DateTime.UtcNow.AddMinutes(-5)),
    ];

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns notifications added after the given ID.</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(int lastSeenId)
    {
        lock (_notifications)
        {
            // Simulate a new notification arriving roughly every 10 seconds.
            if (Random.Shared.Next(2) == 0)
            {
                _notifications.Add(new(_nextId++,
                    $"Background event at {DateTime.UtcNow:T}",
                    DateTime.UtcNow));
            }

            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading…</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("g")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? notifications { get; set; }

    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        // ??= avoids re-fetching data that was already persisted from prerender.
        notifications ??= await NotificationSvc.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender never fires during prerender,
            // so the polling loop only starts once the page is truly interactive.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var lastId = notifications?.Count > 0
                ? notifications.Max(n => n.Id)
                : 0;

            var newer = await NotificationSvc.GetNotificationsSinceAsync(lastId);

            if (newer.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    notifications ??= [];
                    notifications.AddRange(newer);
                    StateHasChanged();
                });
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

