private List<Notification>? notifications;
private PersistingComponentStateSubscription _persistSub;
private CancellationTokenSource? _cts;

protected override async Task OnInitializedAsync()
{
    _persistSub = ApplicationState.RegisterOnPersisting(PersistNotifications);

    if (!ApplicationState.TryTakeFromJson<List<Notification>>(
            nameof(notifications), out var restored))
    {
        notifications = await NotificationSvc.GetNotificationsAsync();
    }
    else
    {
        notifications = restored;
    }
}

private Task PersistNotifications()
{
    ApplicationState.PersistAsJson(nameof(notifications), notifications);
    return Task.CompletedTask;
}

